@dataclass
class Expr:
    """Base class for all expressions."""

    text: str = field(default="", compare=False)


@dataclass
class Literal(Expr):
    value: Any = None


@dataclass
class Column(Expr):
    name: str = ""


@dataclass
class Unary(Expr):
    op: str = ""
    operand: Optional[Expr] = None


@dataclass
class Binary(Expr):
    op: str = ""
    left: Optional[Expr] = None
    right: Optional[Expr] = None


@dataclass
class IsNull(Expr):
    operand: Optional[Expr] = None
    negated: bool = False


@dataclass
class InList(Expr):
    operand: Optional[Expr] = None
    items: List[Expr] = field(default_factory=list)
    negated: bool = False


@dataclass
class Between(Expr):
    operand: Optional[Expr] = None
    low: Optional[Expr] = None
    high: Optional[Expr] = None
    negated: bool = False


@dataclass
class Like(Expr):
    operand: Optional[Expr] = None
    pattern: Optional[Expr] = None
    negated: bool = False


@dataclass
class Call(Expr):
    name: str = ""
    args: List[Expr] = field(default_factory=list)
    star: bool = False


@dataclass
class SelectItem:
    expr: Expr
    alias: Optional[str] = None


@dataclass
class OrderItem:
    expr: Expr
    desc: bool = False


@dataclass
class Query:
    star: bool
    items: List[SelectItem]
    table: str
    distinct: bool = False
    where: Optional[Expr] = None
    group_by: List[Expr] = field(default_factory=list)
    having: Optional[Expr] = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: int = 0


def children(expr: Expr) -> Iterator[Expr]:
    """Yield the direct child expressions of ``expr``."""

    if isinstance(expr, Unary):
        if expr.operand is not None:
            yield expr.operand
    elif isinstance(expr, Binary):
        if expr.left is not None:
            yield expr.left
        if expr.right is not None:
            yield expr.right
    elif isinstance(expr, IsNull):
        if expr.operand is not None:
            yield expr.operand
    elif isinstance(expr, InList):
        if expr.operand is not None:
            yield expr.operand
        yield from expr.items
    elif isinstance(expr, Between):
        if expr.operand is not None:
            yield expr.operand
        if expr.low is not None:
            yield expr.low
        if expr.high is not None:
            yield expr.high
    elif isinstance(expr, Like):
        if expr.operand is not None:
            yield expr.operand
        if expr.pattern is not None:
            yield expr.pattern
    elif isinstance(expr, Call):
        yield from expr.args


def walk(expr: Expr) -> Iterator[Expr]:
    """Yield ``expr`` and all of its descendants (pre-order)."""

    yield expr
    for child in children(expr):
        yield from walk(child)


