    """A hashable structural key for an expression, ignoring ``text``.

    Column names and function names are compared case-insensitively.
    """

    if isinstance(expr, Literal):
        return ("literal", _literal_key(expr.value))
    if isinstance(expr, Column):
        return ("column", expr.name.lower())
    if isinstance(expr, Unary):
        return ("unary", expr.op.upper(), expr_key(expr.operand))
    if isinstance(expr, Binary):
        return (
            "binary",
            expr.op.upper(),
            expr_key(expr.left),
            expr_key(expr.right),
        )
    if isinstance(expr, IsNull):
        return ("isnull", bool(expr.negated), expr_key(expr.operand))
    if isinstance(expr, InList):
        return (
            "in",
            bool(expr.negated),
            expr_key(expr.operand),
            tuple(expr_key(item) for item in expr.items),
        )
    if isinstance(expr, Between):
        return (
            "between",
            bool(expr.negated),
            expr_key(expr.operand),
            expr_key(expr.low),
            expr_key(expr.high),
        )
    if isinstance(expr, Like):
        return (
            "like",
            bool(expr.negated),
            expr_key(expr.operand),
            expr_key(expr.pattern),
        )
    if isinstance(expr, Call):
        return (
            "call",
            expr.name.upper(),
            bool(expr.star),
            tuple(expr_key(arg) for arg in expr.args),
        )
    return (type(expr).__name__, id(expr))


def contains_aggregate(expr: Optional[Expr]) -> bool:
    """Return True if ``expr`` contains an aggregate function call."""

    if expr is None:
        return False
    for node in walk(expr):
        if isinstance(node, Call) and node.name.upper() in AGGREGATE_NAMES:
